async page => {
 const out={checks:[],cases:[]};const check=async(ok,label)=>{if(!ok){out.failure=label;await page.evaluate(out=>sessionStorage.setItem('fix-calls-recovery-result',JSON.stringify(out)),out);throw Error(label);}out.checks.push(label);await page.evaluate(out=>sessionStorage.setItem('fix-calls-recovery-result',JSON.stringify(out)),out);};
 await page.evaluate(()=>{navigateTo('seat-workbench');const s=JSON.parse(sessionStorage.getItem('native-workbench-session-v1')||'null');if(s?.phase==='wrap'){AgentWorkbench.openDialog();AgentWorkbench.saveDisposition();}});
 for(const kind of ['rollback-fails','final-write-fails']){
  await page.evaluate(()=>{navigateTo('seat-workbench');AgentWorkbench.updateField('skillGroupId','SHOWCASE-HQ-SKILL-SALES');AliCtiAdapter.scenario='success';void AgentWorkbench.signIn();});await page.waitForFunction(()=>AgentWorkbench.myAgent()?.currentEndpoint==='NATIVE_WORKBENCH');
  await page.evaluate(()=>{const row=CustomerTasks.mine().find(r=>r.followup==='待联系'&&!r.calls.length);CustomerTasks.pick(row.id);AgentWorkbench.dial();});await page.waitForFunction(()=>document.getElementById('assigned-call-dialog')?.innerText.includes('通话中'));
  const before=await page.evaluate(kind=>{AgentWorkbench.end();AgentWorkbench.setDisposition('已完成沟通');AgentWorkbench.setRemark('恢复验证 '+kind);AgentWorkbench.setFollowup('visitIntention','有意向');const saved=JSON.parse(sessionStorage.getItem('native-workbench-session-v1')),original=Storage.prototype.setItem;let nativeWrites=0;Storage.prototype.setItem=function(k,v){if(k==='native-workbench-records-v1'&&++nativeWrites>1)throw Error('subsequent journal write fails');if(kind==='rollback-fails'&&k==='customer-task-batches-v1')throw Error('customer write fails');return original.call(this,k,v);};try{AgentWorkbench.saveDisposition();}finally{Storage.prototype.setItem=original;}
   const session=JSON.parse(sessionStorage.getItem('native-workbench-session-v1')),record=JSON.parse(localStorage.getItem('native-workbench-records-v1')).find(c=>c.callId===saved.call.callId),customer=CustomerTasks.row(saved.call.customerTaskItemId).r;return {kind,callId:saved.call.callId,itemId:saved.call.customerTaskItemId,status:record.processingStatus,intent:record.pendingDisposition,phase:session.phase,customerStatus:customer.followup,customerActive:customer.activeCallId,error:document.getElementById('seat-error')?.textContent};},kind);
  await check(before.status==='待填写'&&before.phase==='wrap'&&before.intent?.agentDisposition==='已完成沟通',kind+'持久化仅暂存未完成通话，失败不写假完成');
  await page.reload();await page.evaluate(()=>{navigateTo('seat-workbench');AgentWorkbench.openDialog();});
  const restored=await page.evaluate(()=>{const s=JSON.parse(sessionStorage.getItem('native-workbench-session-v1'));return {phase:s.phase,status:s.call?.processingStatus,id:s.call?.callId,disposition:document.getElementById('seat-disposition')?.value,remark:document.getElementById('seat-remark')?.value,intention:document.getElementById('seat-followup-visitIntention')?.value};});
  await check(restored.phase==='wrap'&&restored.status==='待填写'&&restored.id===before.callId&&restored.disposition==='已完成沟通'&&restored.remark==='恢复验证 '+kind&&restored.intention==='有意向',kind+'刷新仍恢复原通话、话后输入及未完成态');
  const after=await page.evaluate(itemId=>{AgentWorkbench.saveDisposition();const row=CustomerTasks.row(itemId).r,s=JSON.parse(sessionStorage.getItem('native-workbench-session-v1'));const record=JSON.parse(localStorage.getItem('native-workbench-records-v1')).find(c=>c.callId===row.calls.at(-1).callId);return {phase:s.phase,active:row.activeCallId,followup:row.followup,status:record.processingStatus,intent:record.pendingDisposition,historyCount:row.calls.length,error:document.getElementById('seat-error')?.textContent};},before.itemId);
  await check(after.phase==='idle'&&!after.active&&after.followup==='已完成'&&after.status==='已完成'&&!after.intent&&after.historyCount===1,kind+'恢复后同次提交完成，解除占用且只一条历史');out.cases.push({before,restored,after});
 }
 const issue=await page.evaluate(()=>CloudCallData.callDataIssues.find(r=>r.issueId==='VIEW-DEMO-HQ-DATA'));await check(issue.type==='历史异常依据待核对'&&Array.isArray(issue.trace)&&issue.status==='待处理','K01旧持久化异常包刷新后迁移结构完整');
 out.complete=true;await page.evaluate(out=>sessionStorage.setItem('fix-calls-recovery-result',JSON.stringify(out)),out);return out;
}
